class ArrayList<T> {
  private items: T[] = [];
  add(item: T) { this.items.push(item); }
  get(index: number) { return this.items[index]; }
  size() { return this.items.length; }
  createIterator() { return new ArrayIterator(this); }
}

class ArrayIterator<T> {
  private i = 0;
  constructor(private list: ArrayList<T>) {}
  next() { return this.list.get(this.i++); }
  hasNext() { return this.i < this.list.size(); }
}

class TreeNode<T> { constructor(public value: T, public left?: TreeNode<T>, public right?: TreeNode<T>) {} }

class Tree<T> {
  constructor(private root?: TreeNode<T>) {}
  traverse(fn: (v: T) => void) { this._walk(this.root, fn); }
  private _walk(node?: TreeNode<T>, fn?: (v: T) => void) { if (!node || !fn) return; fn(node.value); this._walk(node.left, fn); this._walk(node.right, fn); }
}

// Version A: collection holds cursor state
class LogBufferV1 {
  private cursor = 0;
  private entries: string[] = [];
  append(e: string) { this.entries.push(e); }
  next() { return this.entries[this.cursor++]; }
  hasNext() { return this.cursor < this.entries.length; }
}

// Version B: collection creates independent cursors
class LogBufferV2 {
  private entries: string[] = [];
  append(e: string) { this.entries.push(e); }
  createCursor() {
    let i = 0;
    return { next: () => this.entries[i++], hasNext: () => i < this.entries.length };
  }
}
